import sys

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    a = list(map(int, input[1:]))

    parent_count = [0] * n
    for i in range(n):
        if a[i] - 1 != i:
            parent_count[a[i] - 1] += 1

    extra_roots = sum(1 for i in range(n) if parent_count[i] == 0 and i != a[i] - 1)
    missing_parents = sum(1 for count in parent_count if count == 0)

    changes = max(extra_roots, missing_parents)
    root_candidates = [i + 1 for i in range(n) if parent_count[i] == 0]

    for i in range(n):
        if parent_count[a[i] - 1] == 0 and i != a[i] - 1:
            a[i] = root_candidates.pop()
            if not root_candidates:
                break

    while missing_parents > 0:
        for i in range(n):
            if parent_count[a[i] - 1] > 1:
                a[i] = root_candidates.pop()
                parent_count[a[i] - 1] -= 1
                missing_parents -= 1
                if not root_candidates:
                    break

    print(changes)
    print(" ".join(map(str, a)))

if __name__ == "__main__":
    main()
